// 完全二叉树（1..N，i 的孩子 2i,2i+1）
// 以 u 为根的子树中，向下深度恰好 d 的节点数（不越出 N）
ll count_subtree(ll u, ll d, ll N) {
    if (d < 0 || d >= 63) return 0;
    if (u > (N >> d)) return 0;
    ll l = u << d;
    ll r = min(N, ((u + 1) << d) - 1);
    return (l <= r) ? (r - l + 1) : 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        ll N, X, K;
        cin >> N >> X >> K;
        ll ans = count_subtree(X, K, N);     // X 子树向下 K 层
        ll x = X, k = K - 1;                  // 沿祖先向上
        while (x > 1 && k >= 0) {
            if (k == 0) { ans++; break; }     // 祖先本身距离 K
            ll p = x >> 1;                    // 父
            ll bro = (x & 1) ? (x - 1) : (x + 1);  // 兄弟
            if (bro <= N) ans += count_subtree(bro, k - 1, N);
            x = p;
            k--;
        }
        cout << ans << '\n';
    }
    return 0;
}

